ai_sql:
SELECT (COUNT(*) FILTER (WHERE nova_group = 4)::DOUBLE / COUNT(*) ) * 100 AS organic_ultra_processed_share_percent
FROM products
WHERE is_organic = true AND nova_group IS NOT NULL;

SELECT AVG(additives_count)::DOUBLE AS avg_additives
FROM products
WHERE nova_group = 4 AND additives_count IS NOT NULL;

SELECT (COUNT(*) FILTER (WHERE pack_plastic) * 100.0) / COUNT(*) AS plastic_share_percent
FROM products
WHERE food_group = 'Beverages' AND pack_plastic IS NOT NULL;
